113	void A2ADims::validate() const
114	{
115	    if (world_size <= 0) {
116	        fail("world_size must be positive, got " + std::to_string(world_size));
117	    }
118	    if (rank < 0 || rank >= world_size) {
119	        fail("rank " + std::to_string(rank) + " out of range for world_size " + std::to_string(world_size));
120	    }
121	    if (b <= 0 || d <= 0) {
122	        fail("b and d must be positive, got b=" + std::to_string(b) + " d=" + std::to_string(d));
123	    }
124	    if (static_cast<int>(seq_splits.size()) != world_size) {
125	        fail("seq_splits has " + std::to_string(seq_splits.size()) + " entries, expected "
126	             + std::to_string(world_size));
127	    }
128	    if (static_cast<int>(head_splits.size()) != world_size) {
129	        fail("head_splits has " + std::to_string(head_splits.size()) + " entries, expected "
130	             + std::to_string(world_size));
131	    }
132	    // Zero-length shards are allowed (a rank can end up with no sequence), negatives are not.
133	    for (int p = 0; p < world_size; ++p) {
134	        if (seq_splits[p] < 0) {
135	            fail("seq_splits[" + std::to_string(p) + "] is negative");
136	        }
137	        if (head_splits[p] < 0) {
138	            fail("head_splits[" + std::to_string(p) + "] is negative");
139	        }
140	    }
141	}
142	
143	A2APlan build_plan(const A2ADims& dims, int mode, int64_t elem_size)
144	{
145	    dims.validate();
146	    if (elem_size <= 0) {
147	        fail("elem_size must be positive, got " + std::to_string(elem_size));
148	    }
149	    if (mode != kScatterHead && mode != kGatherHead) {
150	        fail("mode must be 0 (scatter head) or 1 (gather head), got " + std::to_string(mode));
151	    }
152	
153	    const int64_t              seq_total   = dims.seq_total();
154	    const int64_t              head_total  = dims.head_total();
155	    const std::vector<int64_t> seq_offset  = dims.seq_offsets();
156	    const std::vector<int64_t> head_offset = dims.head_offsets();
157	    const int64_t              s_me        = dims.seq_splits[dims.rank];
158	    const int64_t              n_me        = dims.head_splits[dims.rank];
159	    check_byte_products(dims, seq_total, head_total, elem_size);
160	    const int64_t d_bytes = dims.d * elem_size;
161	
162	    A2APlan plan;
163	    plan.output_shape = (mode == kScatterHead) ? std::vector<int64_t>{dims.b, seq_total, n_me, dims.d} :
164	                                                 std::vector<int64_t>{dims.b, s_me, head_total, dims.d};
165	
166	    // Window size: the largest receive over all ranks (see A2APlan::window_numel).
167	    for (int p = 0; p < dims.world_size; ++p) {
168	        const int64_t rows       = (mode == kScatterHead) ? seq_total : dims.seq_splits[p];
169	        const int64_t heads      = (mode == kScatterHead) ? dims.head_splits[p] : head_total;
170	        const int64_t peer_numel = checked_mul(
171	            checked_mul(checked_mul(dims.b, rows, "window size"), heads, "window size"), dims.d, "window size");
172	        plan.window_numel = std::max(plan.window_numel, peer_numel);
173	    }
174	
175	    for (int p = 0; p < dims.world_size; ++p) {
176	        if (mode == kScatterHead) {
177	            // Send peer p the head columns it owns, for every local sequence position; they land in
178	            // the slice of p's window that this rank's sequence shard occupies. The window rows are
179	            // contiguous, so this reads strided and writes contiguous.
180	            const int64_t row = dims.head_splits[p] * d_bytes;
181	            if (row == 0 || s_me == 0) {
182	                continue;
183	            }
184	            CopyOp op;
185	            op.peer       = p;
186	            op.src_offset = head_offset[p] * d_bytes;
187	            op.src_pitch  = head_total * d_bytes;
188	            op.dst_offset = seq_offset[dims.rank] * row;
189	            op.dst_pitch  = row;
190	            op.width      = row;
191	            op.rows       = s_me;
192	            push_batched(plan.ops, op, dims.b, s_me * head_total * d_bytes, seq_total * row);
193	        }
194	        else {
195	            // The inverse: send peer p the sequence rows it owns, carrying only this rank's head
196	            // columns, into p's window at this rank's head offset -- a strided write. Landing them
197	            // contiguously in a per-sender segment is not available here: the window IS the
198	            // returned tensor, so there is no local pass to interleave them afterwards.
199	            const int64_t row = n_me * d_bytes;
200	            const int64_t s_p = dims.seq_splits[p];
201	            if (row == 0 || s_p == 0) {
202	                continue;
203	            }
204	            CopyOp op;
205	            op.peer       = p;
206	            op.src_offset = seq_offset[p] * row;
207	            op.src_pitch  = row;
208	            op.dst_offset = head_offset[dims.rank] * d_bytes;
209	            op.dst_pitch  = head_total * d_bytes;
210	            op.width      = row;
211	            op.rows       = s_p;
212	            push_batched(plan.ops, op, dims.b, seq_total * row, s_p * head_total * d_bytes);
213	        }
214	    }
215	    return plan;
216	}
217	
218	}  // namespace ulysses
