140	bool UlyssesGroup::PlanKey::operator<(const PlanKey& o) const
141	{
142	    return std::tie(sizes, seq, head, mode, dtype) < std::tie(o.sizes, o.seq, o.head, o.mode, o.dtype);
143	}
