145	UlyssesGroup::UlyssesGroup(std::string group_name, int64_t rank, int64_t world_size, int64_t device_index):
146	    group_name_(std::move(group_name)),
147	    rank_(static_cast<int>(rank)),
148	    world_size_(static_cast<int>(world_size)),
149	    device_index_(static_cast<int>(device_index))
150	{
151	    TORCH_CHECK(world_size_ >= 1 && world_size_ <= 8,
152	                "world_size must be in [1, 8] -- fast-ulysses is single-node -- got ",
153	                world_size_);
154	    TORCH_CHECK(rank_ >= 0 && rank_ < world_size_, "rank ", rank_, " out of range for world_size ", world_size_);
155	}
