17	// A peer's entry in seq_splits/head_splits is bounded by nothing, and a product that wraps gives a
18	// negative window_numel, which every downstream size check reads as "small enough".
19	int64_t checked_mul(int64_t a, int64_t b, const std::string& what)
20	{
21	    if (a != 0 && b > std::numeric_limits<int64_t>::max() / a) {
22	        fail(what + " overflows int64 (" + std::to_string(a) + " * " + std::to_string(b) + ")");
23	    }
24	    return a * b;
25	}
