52	std::vector<int64_t> exclusive_prefix_sum(const std::vector<int64_t>& values)
53	{
54	    std::vector<int64_t> offsets(values.size(), 0);
55	    int64_t              running = 0;
56	    for (size_t i = 0; i < values.size(); ++i) {
57	        offsets[i] = running;
58	        running += values[i];
59	    }
60	    return offsets;
61	}
