129	        fail("head_splits has " + std::to_string(head_splits.size()) + " entries, expected "
130	             + std::to_string(world_size));
131	    }
132	    // Zero-length shards are allowed (a rank can end up with no sequence), negatives are not.
133	    for (int p = 0; p < world_size; ++p) {
