167	const A2APlan& UlyssesGroup::plan(at::IntArrayRef                            sizes,
168	                                  int64_t                                    mode,
169	                                  at::ScalarType                             dtype,
170	                                  const std::optional<std::vector<int64_t>>& seq_splits,
171	                                  const std::optional<std::vector<int64_t>>& head_splits)
172	{
173	    PlanKey key;
174	    key.sizes = sizes.vec();
175	    key.mode  = mode;
176	    key.dtype = dtype;
177	    // Kept optional, so "no splits" and "empty splits" are distinct keys. Collapsing them would
178	    // let an even-split call warm the cache for a later empty-split one, which make_dims rejects.
179	    key.seq  = seq_splits;
180	    key.head = head_splits;
181	
182	    auto it = plans_.find(key);
183	    if (it != plans_.end()) {
184	        return it->second;
185	    }
186	    // A caller whose shapes are data-dependent would otherwise grow this without bound. Dropping
187	    // everything costs one rebuild per live shape, which is microseconds.
188	    if (plans_.size() >= 512) {
189	        plans_.clear();
190	    }
191	    const A2ADims dims = make_dims(sizes, dtype, mode, world_size_, rank_, seq_splits, head_splits);
192	    return plans_
193	        .emplace(std::move(key),
194	                 build_plan(dims, static_cast<int>(mode), static_cast<int64_t>(c10::elementSize(dtype))))
195	        .first->second;
196	}
